-- 106: HSK 7–9 · шинэ хэлбэр (3.0) · Загвар №1 — өөрсдийн зохиосон загвар шалгалт.
-- 91 асуулт: сонсгол 40, уншлага 47, бичих 2, орчуулга 2. Аудио апп дотроо (/mock-tests/n7-01/). Дахин ажиллуулахад аюулгүй.
begin;

insert into public.mock_tests (id, hsk_level, title, total_questions, time_limit_min, has_writing, sections, is_active)
values ('N7-01', 7, 'HSK 7–9 · шинэ хэлбэр (3.0) · Загвар №1', 91, 173, true, '[{"skill": "listening", "audio_url": "/mock-tests/n7-01/listening.mp3", "time_min": 23, "parts": [{"desc": "Мэдээ сонсоод өгүүлбэр зөв/буруу эсэхийг шүүх", "part": 1, "range": [1, 10], "q_type": "judge"}, {"desc": "Урт яриа сонсоод сонгох / нөхөж бичих", "part": 2, "range": [11, 22], "q_type": "choice"}, {"desc": "Лекц, илтгэл сонсоод сонгох / нөхөж бичих", "part": 3, "range": [23, 40], "q_type": "choice"}]}, {"skill": "reading", "audio_url": null, "time_min": 60, "parts": [{"desc": "Урт эх унших → асуултын хариу сонгох", "part": 1, "range": [41, 68], "q_type": "choice"}, {"desc": "Догол мөрүүдийг зөв дараалалд оруулах", "part": 2, "range": [69, 73], "q_type": "choice"}, {"desc": "Эх уншаад товч хариулт бичих", "part": 3, "range": [74, 87], "q_type": "essay"}]}, {"skill": "writing", "audio_url": null, "time_min": 90, "parts": [{"desc": "График тайлбарлах (200 орчим ханз)", "part": 1, "range": [88, 88], "q_type": "essay_picture"}, {"desc": "Сэдэвт зохион бичлэг (600 орчим ханз)", "part": 2, "range": [89, 89], "q_type": "essay"}, {"desc": "Орчуулга: монгол → хятад", "part": 3, "range": [90, 91], "q_type": "essay"}]}]'::jsonb, true)
on conflict (id) do update set hsk_level=excluded.hsk_level, title=excluded.title, total_questions=excluded.total_questions,
  time_limit_min=excluded.time_limit_min, has_writing=excluded.has_writing, sections=excluded.sections, is_active=excluded.is_active;

insert into public.mock_test_questions
  (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note)
values
  ('N7-01', 'listening', 1, 1, 'judge', '口袋公园一般建在城市的大片空地上。', null, '×', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«利用街角、桥下、楼宇之间的零散空地» — гудамжны булан, гүүрэн доорх ЖИЖИГ, тархай зайг ашигладаг. «大片空地» (том талбай) биш.', 14.0, 89.6, '近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。
据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。
不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。', '{"transcript": [{"zh": "近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。"}, {"zh": "据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。"}, {"zh": "不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。"}], "why": "«利用街角、桥下、楼宇之间的零散空地» — гудамжны булан, гүүрэн доорх ЖИЖИГ, тархай зайг ашигладаг. «大片空地» (том талбай) биш."}'::jsonb),
  ('N7-01', 'listening', 1, 2, 'judge', '过去三年新建的口袋公园大多数在老城区。', null, '√', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«七成以上位于人口密集的老城区» — 70%-иас дээш нь хуучин хороололд.', 14.0, 98.6, '近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。
据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。
不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。', '{"transcript": [{"zh": "近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。"}, {"zh": "据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。"}, {"zh": "不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。"}], "why": "«七成以上位于人口密集的老城区» — 70%-иас дээш нь хуучин хороололд."}'::jsonb),
  ('N7-01', 'listening', 1, 3, 'judge', '口袋公园的建设成本比大型公园高。', null, '×', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«造价仅为前者的十分之一左右» — том цэцэрлэгийн аравны нэг орчим л зардалтай.', 14.0, 107.6, '近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。
据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。
不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。', '{"transcript": [{"zh": "近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。"}, {"zh": "据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。"}, {"zh": "不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。"}], "why": "«造价仅为前者的十分之一左右» — том цэцэрлэгийн аравны нэг орчим л зардалтай."}'::jsonb),
  ('N7-01', 'listening', 1, 4, 'judge', '口袋公园的日常维护费用很低。', null, '×', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«日常维护的成本并不低» — «并不低» = бага биш. Олон, тархай учраас арчилгаа зардалтай.', 14.0, 116.6, '近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。
据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。
不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。', '{"transcript": [{"zh": "近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。"}, {"zh": "据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。"}, {"zh": "不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。"}], "why": "«日常维护的成本并不低» — «并不低» = бага биш. Олон, тархай учраас арчилгаа зардалтай."}'::jsonb),
  ('N7-01', 'listening', 1, 5, 'judge', '“认领”公园的做法将来会在全市推广。', null, '√', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«今后将在全市范围内逐步推广» — цаашид хот даяар аажмаар нэвтрүүлнэ.', 14.0, 125.6, '近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。
据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。
不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。', '{"transcript": [{"zh": "近年来，一种被称为“口袋公园”的小型绿地正在各大城市悄然兴起。所谓口袋公园，是指利用街角、桥下、楼宇之间的零散空地改造而成的微型公园，面积通常不超过五千平方米，有的甚至只有几百平方米。"}, {"zh": "据市园林部门统计，本市过去三年共建成口袋公园四百二十六处，其中七成以上位于人口密集的老城区。与大型公园相比，口袋公园的造价仅为前者的十分之一左右，建设周期也短得多，一般三个月就能完工。"}, {"zh": "不过，口袋公园也面临管理上的难题。由于数量多、分布散，日常维护的成本并不低。为此，部分街道尝试让附近的居民和商户“认领”公园，负责日常的清洁和绿化养护，政府则给予一定的补贴。有关人士表示，这种做法既减轻了财政压力，也增强了居民的归属感，今后将在全市范围内逐步推广。"}], "why": "«今后将在全市范围内逐步推广» — цаашид хот даяар аажмаар нэвтрүүлнэ."}'::jsonb),
  ('N7-01', 'listening', 1, 6, 'judge', '这艘潜水器是从国外引进的。', null, '×', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«我国自主研制的» — өөрсдөө судалж бүтээсэн, гаднаас авчраагүй.', 134.2, 207.2, '昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。
此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。
值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。', '{"transcript": [{"zh": "昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。"}, {"zh": "此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。"}, {"zh": "值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。"}], "why": "«我国自主研制的» — өөрсдөө судалж бүтээсэн, гаднаас авчраагүй."}'::jsonb),
  ('N7-01', 'listening', 1, 7, 'judge', '这次下潜创造了该型号潜水器新的深度纪录。', null, '√', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«再次刷新了该型号潜水器的作业纪录» — «刷新纪录» = дээд амжилт шинэчлэх.', 134.2, 216.2, '昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。
此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。
值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。', '{"transcript": [{"zh": "昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。"}, {"zh": "此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。"}, {"zh": "值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。"}], "why": "«再次刷新了该型号潜水器的作业纪录» — «刷新纪录» = дээд амжилт шинэчлэх."}'::jsonb),
  ('N7-01', 'listening', 1, 8, 'judge', '科考队在海底发现了一些以前没有记录过的物种。', null, '√', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«发现了多个此前从未记录过的物种» — урьд өмнө бүртгэгдээгүй хэд хэдэн зүйл.', 134.2, 225.2, '昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。
此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。
值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。', '{"transcript": [{"zh": "昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。"}, {"zh": "此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。"}, {"zh": "值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。"}], "why": "«发现了多个此前从未记录过的物种» — урьд өмнө бүртгэгдээгүй хэд хэдэн зүйл."}'::jsonb),
  ('N7-01', 'listening', 1, 9, 'judge', '科研人员必须等潜水器回到海面才能看到海底画面。', null, '×', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«高清视频实时传输…在船上就能同步观看» — бодит цагаар шууд дамжуулж, хөлөг дээрээс зэрэг үзсэн.', 134.2, 234.2, '昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。
此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。
值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。', '{"transcript": [{"zh": "昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。"}, {"zh": "此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。"}, {"zh": "值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。"}], "why": "«高清视频实时传输…在船上就能同步观看» — бодит цагаар шууд дамжуулж, хөлөг дээрээс зэрэг үзсэн."}'::jsonb),
  ('N7-01', 'listening', 1, 10, 'judge', '相关研究成果已经全部对外公布。', null, '×', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.news']::text[], '«相关研究成果将陆续对外公布» — «将陆续» = цаашид аажмаар зарлана, одоогоор зарлаагүй.', 134.2, 243.2, '昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。
此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。
值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。', '{"transcript": [{"zh": "昨天上午，我国自主研制的新一代深海载人潜水器在西太平洋海域完成了本年度的最后一次下潜任务，最大下潜深度达到一万零九百米，再次刷新了该型号潜水器的作业纪录。"}, {"zh": "此次科学考察历时五十二天，共完成下潜二十三次，采集到岩石、沉积物和深海生物样品三百余件。科考队首席科学家介绍，他们在海沟底部发现了多个此前从未记录过的物种，其中一种身体透明的小型鱼类引起了研究人员的极大兴趣。"}, {"zh": "值得一提的是，这次任务首次实现了潜水器与海面母船之间的高清视频实时传输，科研人员在船上就能同步观看海底画面，并指挥潜水器调整采样位置。专家指出，这项技术大大提高了深海作业的效率，也为今后开展无人化深海探测打下了基础。全部样品预计下月运抵国内实验室，相关研究成果将陆续对外公布。"}], "why": "«相关研究成果将陆续对外公布» — «将陆续» = цаашид аажмаар зарлана, одоогоор зарлаагүй."}'::jsonb),
  ('N7-01', 'listening', 2, 11, 'choice', '周远认为这个奖应该属于谁？', '[{"key": "A", "text": "他自己和开发商"}, {"key": "B", "text": "团队和老街的居民"}, {"key": "C", "text": "政府有关部门"}, {"key": "D", "text": "国际评奖机构"}]'::jsonb, 'B', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.dialogue']::text[], '«它属于整个团队，更属于一直住在那条街上的居民».', 264.9, 411.9, '女：各位听众好，欢迎收听《城市会客厅》。今天我们请到的是著名建筑师周远先生。周先生，您主持的南城老街改造项目最近获得了国际大奖，首先祝贺您。
男：谢谢。其实这个奖不属于我个人，它属于整个团队，更属于一直住在那条街上的居民。
女：很多旧城改造都是把老房子全部拆掉，重新盖楼。您为什么选择了完全不同的做法？
男：推倒重来当然最省事，开发商也最欢迎，因为能盖更多的房子、卖更多的钱。但是一条街的价值不只在建筑本身，更在于生活在里面的人，以及几十年、上百年形成的邻里关系。房子拆了可以再盖，这种关系一旦断了，就再也找不回来了。
女：那具体来说，你们是怎么做的呢？
男：我们用了一年半的时间，一户一户地上门调查，把每栋房子的状况、每户人家的需求都记录下来，最后把房子分成三类：结构完好的只做修缮；部分损坏的进行加固；实在无法使用的才拆除重建，而且新建筑的高度、颜色都要和周围保持协调。整条街原有的十二条巷子，一条都没有改动。
女：改造期间居民需要搬走吗？
男：这正是最难的地方。我们采取分段施工的办法，每次只动一小段，居民就近临时安置，工程一结束马上搬回来。这样做工期比原计划延长了近一年，成本也增加了大约百分之二十。
女：增加的成本由谁来承担？
男：主要由政府承担，另外一部分来自改造后新增的商业店铺的租金。老街现在成了很受欢迎的文化街区，店铺的收入完全可以覆盖后期的维护费用。
女：最后一个问题，您认为这个项目最大的成功是什么？
男：不是拿奖，而是改造完成后，百分之九十以上的老住户都选择留了下来。对我来说，这比任何奖项都重要。', '{"transcript": [{"zh": "女：各位听众好，欢迎收听《城市会客厅》。今天我们请到的是著名建筑师周远先生。周先生，您主持的南城老街改造项目最近获得了国际大奖，首先祝贺您。"}, {"zh": "男：谢谢。其实这个奖不属于我个人，它属于整个团队，更属于一直住在那条街上的居民。"}, {"zh": "女：很多旧城改造都是把老房子全部拆掉，重新盖楼。您为什么选择了完全不同的做法？"}, {"zh": "男：推倒重来当然最省事，开发商也最欢迎，因为能盖更多的房子、卖更多的钱。但是一条街的价值不只在建筑本身，更在于生活在里面的人，以及几十年、上百年形成的邻里关系。房子拆了可以再盖，这种关系一旦断了，就再也找不回来了。"}, {"zh": "女：那具体来说，你们是怎么做的呢？"}, {"zh": "男：我们用了一年半的时间，一户一户地上门调查，把每栋房子的状况、每户人家的需求都记录下来，最后把房子分成三类：结构完好的只做修缮；部分损坏的进行加固；实在无法使用的才拆除重建，而且新建筑的高度、颜色都要和周围保持协调。整条街原有的十二条巷子，一条都没有改动。"}, {"zh": "女：改造期间居民需要搬走吗？"}, {"zh": "男：这正是最难的地方。我们采取分段施工的办法，每次只动一小段，居民就近临时安置，工程一结束马上搬回来。这样做工期比原计划延长了近一年，成本也增加了大约百分之二十。"}, {"zh": "女：增加的成本由谁来承担？"}, {"zh": "男：主要由政府承担，另外一部分来自改造后新增的商业店铺的租金。老街现在成了很受欢迎的文化街区，店铺的收入完全可以覆盖后期的维护费用。"}, {"zh": "女：最后一个问题，您认为这个项目最大的成功是什么？"}, {"zh": "男：不是拿奖，而是改造完成后，百分之九十以上的老住户都选择留了下来。对我来说，这比任何奖项都重要。"}], "why": "«它属于整个团队，更属于一直住在那条街上的居民»."}'::jsonb),
  ('N7-01', 'listening', 2, 12, 'choice', '周远为什么不赞成“推倒重来”？', '[{"key": "A", "text": "成本太高"}, {"key": "B", "text": "工期太长"}, {"key": "C", "text": "会破坏原有的邻里关系"}, {"key": "D", "text": "开发商不同意"}]'::jsonb, 'C', 'auto', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.dialogue']::text[], '«这种关系一旦断了，就再也找不回来了» — хөршийн харилцаа тасарвал сэргээх боломжгүй. Нураагаад шинээр барих нь харин «最省事».', 264.9, 424.9, '女：各位听众好，欢迎收听《城市会客厅》。今天我们请到的是著名建筑师周远先生。周先生，您主持的南城老街改造项目最近获得了国际大奖，首先祝贺您。
男：谢谢。其实这个奖不属于我个人，它属于整个团队，更属于一直住在那条街上的居民。
女：很多旧城改造都是把老房子全部拆掉，重新盖楼。您为什么选择了完全不同的做法？
男：推倒重来当然最省事，开发商也最欢迎，因为能盖更多的房子、卖更多的钱。但是一条街的价值不只在建筑本身，更在于生活在里面的人，以及几十年、上百年形成的邻里关系。房子拆了可以再盖，这种关系一旦断了，就再也找不回来了。
女：那具体来说，你们是怎么做的呢？
男：我们用了一年半的时间，一户一户地上门调查，把每栋房子的状况、每户人家的需求都记录下来，最后把房子分成三类：结构完好的只做修缮；部分损坏的进行加固；实在无法使用的才拆除重建，而且新建筑的高度、颜色都要和周围保持协调。整条街原有的十二条巷子，一条都没有改动。
女：改造期间居民需要搬走吗？
男：这正是最难的地方。我们采取分段施工的办法，每次只动一小段，居民就近临时安置，工程一结束马上搬回来。这样做工期比原计划延长了近一年，成本也增加了大约百分之二十。
女：增加的成本由谁来承担？
男：主要由政府承担，另外一部分来自改造后新增的商业店铺的租金。老街现在成了很受欢迎的文化街区，店铺的收入完全可以覆盖后期的维护费用。
女：最后一个问题，您认为这个项目最大的成功是什么？
男：不是拿奖，而是改造完成后，百分之九十以上的老住户都选择留了下来。对我来说，这比任何奖项都重要。', '{"transcript": [{"zh": "女：各位听众好，欢迎收听《城市会客厅》。今天我们请到的是著名建筑师周远先生。周先生，您主持的南城老街改造项目最近获得了国际大奖，首先祝贺您。"}, {"zh": "男：谢谢。其实这个奖不属于我个人，它属于整个团队，更属于一直住在那条街上的居民。"}, {"zh": "女：很多旧城改造都是把老房子全部拆掉，重新盖楼。您为什么选择了完全不同的做法？"}, {"zh": "男：推倒重来当然最省事，开发商也最欢迎，因为能盖更多的房子、卖更多的钱。但是一条街的价值不只在建筑本身，更在于生活在里面的人，以及几十年、上百年形成的邻里关系。房子拆了可以再盖，这种关系一旦断了，就再也找不回来了。"}, {"zh": "女：那具体来说，你们是怎么做的呢？"}, {"zh": "男：我们用了一年半的时间，一户一户地上门调查，把每栋房子的状况、每户人家的需求都记录下来，最后把房子分成三类：结构完好的只做修缮；部分损坏的进行加固；实在无法使用的才拆除重建，而且新建筑的高度、颜色都要和周围保持协调。整条街原有的十二条巷子，一条都没有改动。"}, {"zh": "女：改造期间居民需要搬走吗？"}, {"zh": "男：这正是最难的地方。我们采取分段施工的办法，每次只动一小段，居民就近临时安置，工程一结束马上搬回来。这样做工期比原计划延长了近一年，成本也增加了大约百分之二十。"}, {"zh": "女：增加的成本由谁来承担？"}, {"zh": "男：主要由政府承担，另外一部分来自改造后新增的商业店铺的租金。老街现在成了很受欢迎的文化街区，店铺的收入完全可以覆盖后期的维护费用。"}, {"zh": "女：最后一个问题，您认为这个项目最大的成功是什么？"}, {"zh": "男：不是拿奖，而是改造完成后，百分之九十以上的老住户都选择留了下来。对我来说，这比任何奖项都重要。"}], "why": "«这种关系一旦断了，就再也找不回来了» — хөршийн харилцаа тасарвал сэргээх боломжгүй. Нураагаад шинээр барих нь харин «最省事»."}'::jsonb),
  ('N7-01', 'listening', 2, 13, 'complete', '整条街原有的______条巷子都没有改动。（请填写数字）', null, '十二 / 12', 'strict', 1, '/mock-tests/n7-01/listening.mp3', null, false, array['sk.listening.dialogue','sk.listening.fill']::text[], '«整条街原有的十二条巷子，一条都没有改动».', 264.9, 437.9, '女：各位听众好，欢迎收听《城市会客厅》。今天我们请到的是著名建筑师周远先生。周先生，您主持的南城老街改造项目最近获得了国际大奖，首先祝贺您。
男：谢谢。其实这个奖不属于我个人，它属于整个团队，更属于一直住在那条街上的居民。
女：很多旧城改造都是把老房子全部拆掉，重新盖楼。您为什么选择了完全不同的做法？
男：推倒重来当然最省事，开发商也最欢迎，因为能盖更多的房子、卖更多的钱。但是一条街的价值不只在建筑本身，更在于生活在里面的人，以及几十年、上百年形成的邻里关系。房子拆了可以再盖，这种关系一旦断了，就再也找不回来了。
女：那具体来说，你们是怎么做的呢？
男：我们用了一年半的时间，一户一户地上门调查，把每栋房子的状况、每户人家的需求都记录下来，最后把房子分成三类：结构完好的只做修缮；部分损坏的进行加固；实在无法使用的才拆除重建，而且新建筑的高度、颜色都要和周围保持协调。整条街原有的十二条巷子，一条都没有改动。
女：改造期间居民需要搬走吗？
男：这正是最难的地方。我们采取分段施工的办法，每次只动一小段，居民就近临时安置，工程一结束马上搬回来。这样做工期比原计划延长了近一年，成本也增加了大约百分之二十。
女：增加的成本由谁来承担？
男：主要由政府承担，另外一部分来自改造后新增的商业店铺的租金。老街现在成了很受欢迎的文化街区，店铺的收入完全可以覆盖后期的维护费用。
女：最后一个问题，您认为这个项目最大的成功是什么？
男：不是拿奖，而是改造完成后，百分之九十以上的老住户都选择留了下来。对我来说，这比任何奖项都重要。', '{"transcript": [{"zh": "女：各位听众好，欢迎收听《城市会客厅》。今天我们请到的是著名建筑师周远先生。周先生，您主持的南城老街改造项目最近获得了国际大奖，首先祝贺您。"}, {"zh": "男：谢谢。其实这个奖不属于我个人，它属于整个团队，更属于一直住在那条街上的居民。"}, {"zh": "女：很多旧城改造都是把老房子全部拆掉，重新盖楼。您为什么选择了完全不同的做法？"}, {"zh": "男：推倒重来当然最省事，开发商也最欢迎，因为能盖更多的房子、卖更多的钱。但是一条街的价值不只在建筑本身，更在于生活在里面的人，以及几十年、上百年形成的邻里关系。房子拆了可以再盖，这种关系一旦断了，就再也找不回来了。"}, {"zh": "女：那具体来说，你们是怎么做的呢？"}, {"zh": "男：我们用了一年半的时间，一户一户地上门调查，把每栋房子的状况、每户人家的需求都记录下来，最后把房子分成三类：结构完好的只做修缮；部分损坏的进行加固；实在无法使用的才拆除重建，而且新建筑的高度、颜色都要和周围保持协调。整条街原有的十二条巷子，一条都没有改动。"}, {"zh": "女：改造期间居民需要搬走吗？"}, {"zh": "男：这正是最难的地方。我们采取分段施工的办法，每次只动一小段，居民就近临时安置，工程一结束马上搬回来。这样做工期比原计划延长了近一年，成本也增加了大约百分之二十。"}, {"zh": "女：增加的成本由谁来承担？"}, {"zh": "男：主要由政府承担，另外一部分来自改造后新增的商业店铺的租金。老街现在成了很受欢迎的文化街区，店铺的收入完全可以覆盖后期的维护费用。"}, {"zh": "女：最后一个问题，您认为这个项目最大的成功是什么？"}, {"zh": "男：不是拿奖，而是改造完成后，百分之九十以上的老住户都选择留了下来。对我来说，这比任何奖项都重要。"}], "why": "«整条街原有的十二条巷子，一条都没有改动»."}'::jsonb),
