★ 作者为什么认为把责任全推给个人意志力是不公平的？', '[{"key": "A", "text": "因为人的意志力天生很弱"}, {"key": "B", "text": "因为有大量专业人员在研究如何吸引用户"}, {"key": "C", "text": "因为手机价格太贵"}, {"key": "D", "text": "因为法律没有相关规定"}]'::jsonb, 'B', 'auto', 1, null, null, false, array['sk.reading.comprehension','voc.hsk7']::text[], '«屏幕另一边有成千上万名工程师在研究如何吸引你».', null, null, null, null),
